-- Manual setup of one layer (example: tabo_site_extent), to paste in
-- QGIS > Database > DB Manager > SQL window, connected with a data manager account.

-- 1. Reference table: owner, tracking columns, rights, audit
ALTER TABLE private.tabo_site_extent OWNER TO sig_proprietaire;
-- If the primary key is the GeoPackage fid (bigint, no automatic numbering):
-- ALTER TABLE private.tabo_site_extent ALTER COLUMN fid TYPE integer;   -- Lizmap: no bigint key
-- ALTER TABLE private.tabo_site_extent ALTER COLUMN fid ADD GENERATED BY DEFAULT AS IDENTITY;
-- SELECT setval(pg_get_serial_sequence('private.tabo_site_extent', 'fid'),
--               (SELECT max(fid) FROM private.tabo_site_extent));
ALTER TABLE private.tabo_site_extent
    ADD COLUMN IF NOT EXISTS modifie_par text,
    ADD COLUMN IF NOT EXISTS modifie_le timestamp(0) DEFAULT localtimestamp(0);
GRANT SELECT ON private.tabo_site_extent TO sig_lecture;
GRANT INSERT, UPDATE, DELETE ON private.tabo_site_extent TO sig_validation;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA private TO sig_validation;
SELECT audit.audit_table('private.tabo_site_extent', true, true);

-- 2. Proposals table: the business columns of the reference, geometry in 2D,
--    plus the proposal columns
CREATE TABLE propositions.tabo_site_extent AS
    SELECT * FROM private.tabo_site_extent WITH NO DATA;
ALTER TABLE propositions.tabo_site_extent
    DROP COLUMN id,
    DROP COLUMN modifie_par,
    DROP COLUMN modifie_le,
    ALTER COLUMN geom TYPE geometry(Polygon, 32636) USING ST_Force2D(geom),
    ADD COLUMN id_proposition serial PRIMARY KEY,
    ADD COLUMN operation text NOT NULL DEFAULT 'INSERT' CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')),
    ADD COLUMN id_reference integer REFERENCES private.tabo_site_extent (id) ON DELETE SET NULL,
    ADD COLUMN propose_par text,
    ADD COLUMN propose_le timestamp(0) NOT NULL DEFAULT localtimestamp(0),
    ADD COLUMN statut text NOT NULL DEFAULT 'en_attente' CHECK (statut IN ('en_attente', 'validee', 'refusee')),
    ADD COLUMN valide_par text,
    ADD COLUMN valide_le timestamp(0),
    ADD COLUMN commentaire text;
ALTER TABLE propositions.tabo_site_extent OWNER TO sig_proprietaire;
CREATE INDEX ON propositions.tabo_site_extent USING gist (geom);
CREATE INDEX ON propositions.tabo_site_extent (id_reference);
CREATE INDEX ON propositions.tabo_site_extent (statut);
CREATE TRIGGER controle BEFORE INSERT OR UPDATE ON propositions.tabo_site_extent
    FOR EACH ROW EXECUTE FUNCTION propositions.controle();
CREATE TRIGGER supprimer_controle BEFORE DELETE ON propositions.tabo_site_extent
    FOR EACH ROW EXECUTE FUNCTION propositions.supprimer_controle();
GRANT SELECT ON propositions.tabo_site_extent TO sig_lecture;
GRANT INSERT, UPDATE, DELETE ON propositions.tabo_site_extent TO sig_contribution;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA propositions TO sig_contribution;

-- 3. Validate and refuse. Every business column is listed: an INSERT copies it,
--    an UPDATE keeps the current value when the field was left empty.
CREATE FUNCTION propositions.valider_tabo_site_extent(p_id integer, p_commentaire text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
    prop propositions.tabo_site_extent%ROWTYPE;
BEGIN
    SELECT * INTO prop FROM propositions.tabo_site_extent
     WHERE id_proposition = p_id AND statut = 'en_attente' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Proposition % introuvable ou déjà traitée', p_id;
    END IF;
    IF prop.operation = 'INSERT' THEN
        INSERT INTO private.tabo_site_extent
            (id_site, name, country, site_type, chronology, main_phases, description,
             mission_name, director, excavation_start, excavation_end, campaigns, partners,
             institutions, last_update_gis, bibliography, integral_name, state, url, photo,
             geom, modifie_par)
        VALUES
            (prop.id_site, prop.name, prop.country, prop.site_type, prop.chronology, prop.main_phases, prop.description,
             prop.mission_name, prop.director, prop.excavation_start, prop.excavation_end, prop.campaigns, prop.partners,
             prop.institutions, prop.last_update_gis, prop.bibliography, prop.integral_name, prop.state, prop.url, prop.photo,
             ST_Force3DZ(prop.geom), prop.propose_par);
    ELSIF prop.id_reference IS NULL THEN
        RAISE EXCEPTION 'Proposition % : objet concerné non indiqué', p_id;
    ELSIF prop.operation = 'UPDATE' THEN
        UPDATE private.tabo_site_extent SET
            id_site          = coalesce(nullif(prop.id_site, ''), id_site),
            name             = coalesce(nullif(prop.name, ''), name),
            country          = coalesce(nullif(prop.country, ''), country),
            site_type        = coalesce(nullif(prop.site_type, ''), site_type),
            chronology       = coalesce(nullif(prop.chronology, ''), chronology),
            main_phases      = coalesce(nullif(prop.main_phases, ''), main_phases),
            description      = coalesce(nullif(prop.description, ''), description),
            mission_name     = coalesce(nullif(prop.mission_name, ''), mission_name),
            director         = coalesce(nullif(prop.director, ''), director),
            excavation_start = coalesce(nullif(prop.excavation_start, ''), excavation_start),
            excavation_end   = coalesce(nullif(prop.excavation_end, ''), excavation_end),
            campaigns        = coalesce(nullif(prop.campaigns, ''), campaigns),
            partners         = coalesce(nullif(prop.partners, ''), partners),
            institutions     = coalesce(nullif(prop.institutions, ''), institutions),
            last_update_gis  = coalesce(nullif(prop.last_update_gis, ''), last_update_gis),
            bibliography     = coalesce(nullif(prop.bibliography, ''), bibliography),
            integral_name    = coalesce(nullif(prop.integral_name, ''), integral_name),
            state            = coalesce(nullif(prop.state, ''), state),
            url              = coalesce(nullif(prop.url, ''), url),
            photo            = coalesce(nullif(prop.photo, ''), photo),
            geom             = coalesce(ST_Force3DZ(prop.geom), geom),
            modifie_par      = prop.propose_par,
            modifie_le       = localtimestamp(0)
         WHERE id = prop.id_reference;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Proposition % : l''objet % n''existe plus', p_id, prop.id_reference;
        END IF;
    ELSE
        DELETE FROM private.tabo_site_extent WHERE id = prop.id_reference;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Proposition % : l''objet % n''existe plus', p_id, prop.id_reference;
        END IF;
    END IF;
    UPDATE propositions.tabo_site_extent
       SET statut = 'validee', valide_par = session_user, valide_le = localtimestamp(0),
           commentaire = coalesce(p_commentaire, commentaire)
     WHERE id_proposition = p_id;
END $$;

CREATE FUNCTION propositions.refuser_tabo_site_extent(p_id integer, p_commentaire text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
    UPDATE propositions.tabo_site_extent
       SET statut = 'refusee', valide_par = session_user, valide_le = localtimestamp(0),
           commentaire = coalesce(p_commentaire, commentaire)
     WHERE id_proposition = p_id AND statut = 'en_attente';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Proposition % introuvable ou déjà traitée', p_id;
    END IF;
END $$;
ALTER FUNCTION propositions.valider_tabo_site_extent(integer, text) OWNER TO sig_proprietaire;
ALTER FUNCTION propositions.refuser_tabo_site_extent(integer, text) OWNER TO sig_proprietaire;
REVOKE ALL ON FUNCTION propositions.valider_tabo_site_extent(integer, text),
                       propositions.refuser_tabo_site_extent(integer, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION propositions.valider_tabo_site_extent(integer, text),
                          propositions.refuser_tabo_site_extent(integer, text) TO sig_validation;
